1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.Objects;
21	
22	/**
23	 * Maps Owner &amp; OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /**
29	     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
30	     * already been created on the same registration date.
31	     */
32	    private static final int BULK_SIGNUP_THRESHOLD = 80;
33	
34	    @Autowired
35	    protected ClinicService clinicService;
36	
37	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
38	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
39	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
40	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
41	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
42	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
43	    @Mapping(target = "locality", expression = "java(locality(owner))")
44	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
45	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
46	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
47	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
48	    public abstract OwnerDto toOwnerDto(Owner owner);
49	
50	    /**
51	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
52	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
53	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
54	     * the registration date (against which the age is measured) is absent.
55	     */
56	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
57	        LocalDate birthDate = owner.getBirthDate();
58	        LocalDate registrationDate = owner.getRegistrationDate();
59	        if (birthDate == null || registrationDate == null) {
60	            return null;
61	        }
62	        int age = Period.between(birthDate, registrationDate).getYears();
63	        if (age < 18) {
64	            return OwnerDto.AgeBandEnum.MINOR;
65	        }
66	        if (age < 65) {
67	            return OwnerDto.AgeBandEnum.ADULT;
68	        }
69	        return OwnerDto.AgeBandEnum.SENIOR;
70	    }
71	
72	    /**
73	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
74	     * longest first so the correct code is matched before a shorter prefix of it. Australia
75	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
76	     * endpoint normalizes against.
77	     */
78	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
79	
80	    /**
81	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
82	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
83	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
84	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
85	     */
86	    protected String telephoneDisplay(Owner owner) {
87	        String telephone = owner.getTelephone();
88	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
89	            return telephone;
90	        }
91	        String digits = telephone.substring(1);
92	        String countryCode = KNOWN_COUNTRY_CODES.stream()
93	            .filter(digits::startsWith)
94	            .findFirst()
95	            .orElse("");
96	        String national = digits.substring(countryCode.length());
97	        StringBuilder grouped = new StringBuilder();
98	        for (int i = 0; i < national.length(); i++) {
99	            if (i > 0 && i % 3 == 0) {
100	                grouped.append(' ');
101	            }
102	            grouped.append(national.charAt(i));
103	        }
104	        return "+" + countryCode + " " + grouped;
105	    }
106	
107	    /**
108	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
109	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
110	     * email or householdId contributes an empty segment.
111	     */
112	    protected String identityKey(Owner owner) {
113	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
114	        String email = owner.getEmail() == null ? "" : owner.getEmail();
115	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
116	        return telephone + "|" + email + "|" + householdId;
117	    }
118	
119	    /**
120	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
121	     * present, otherwise {@code PHONE}.
122	     */
123	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
124	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
125	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
126	    }
127	
128	    /**
129	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
130	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
133	        "NSW", new int[] {2000, 2099},
134	        "VIC", new int[] {3000, 3099},
135	        "QLD", new int[] {4000, 4099});
136	
137	    /**
138	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
139	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
140	     * moves in lockstep with the identity assigned on create. When no customer code has been
141	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
